main.script:
document.addEventListener('DOMContentLoaded', function() {
    var filterButtons = document.querySelectorAll('[data-filter-cluster]');
    var industryCards = document.querySelectorAll('.industry-card-item');
    var searchInput = document.getElementById('industrySearchInput');
    var countEl = document.getElementById('industryVisibleCount');

    function applyFilter() {
        var activeBtn = document.querySelector('[data-filter-cluster].active');
        var activeCluster = activeBtn ? activeBtn.getAttribute('data-filter-cluster') : 'all';
        var query = searchInput ? searchInput.value.toLowerCase().trim() : '';
        var visible = 0;

        industryCards.forEach(function(card) {
            var cluster = card.getAttribute('data-cluster');
            var searchContent = (card.getAttribute('data-search') || '').toLowerCase();
            var matchesCluster = (activeCluster === 'all' || cluster === activeCluster);
            var matchesQuery = (query === '' || searchContent.indexOf(query) !== -1);

            if (matchesCluster && matchesQuery) {
                card.style.display = 'block';
                visible++;
            } else {
                card.style.display = 'none';
            }
        });

        if (countEl) {
            countEl.textContent = visible;
        }
    }

    filterButtons.forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            filterButtons.forEach(function(b) {
                b.classList.remove('active');
                b.classList.remove('btn-primary');
                b.classList.add('btn-outline-secondary');
            });
            this.classList.remove('btn-outline-secondary');
            this.classList.add('active');
            this.classList.add('btn-primary');
            applyFilter();
        });
    });

    if (searchInput) {
        searchInput.addEventListener('input', applyFilter);
    }
});
